if (typeof msg.statusCode !== 'number') {
    const detail = String(msg.statusCode || '') + ' ' + String(msg.payload || '');
    msg.statusCode = 502;
    msg.payload = JSON.stringify({code: 'NODE_RED_PROXY', error: '[NODE_RED_PROXY] Sin respuesta de main.py (127.0.0.1:8000). La orden no se confirmo.', detail: detail.trim()});
}
return msg;
